INSERT INTO templates (id, domain, scheme, name, description, version, frequency_days, active) VALUES (1, 'food', 'fssai1', 'FSSAI Schedule 4 & FDCA readiness (39 checkpoints)', 'Used for the first round of visits, Aug 2026.', 1, 30, 0);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (1, 1, 'S1', 'A. Service Area', NULL, 'Both', 'FSSAI licence displayed and valid; Food Safety Display Board put up', NULL, 1, NULL, 4, 'paperwork', 1);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (2, 1, 'S2', 'A. Service Area', NULL, 'Both', 'FSSAI licence number printed on menu', NULL, 0, NULL, 2, 'paperwork', 2);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (3, 1, 'S3', 'A. Service Area', NULL, 'Both', 'Tables, chairs and other guest-area surfaces clean and sanitised', NULL, 0, NULL, 2, 'physical', 3);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (4, 1, 'S4', 'A. Service Area', NULL, 'Both', 'Floors, walls, ceiling clean — no cobwebs, seepage or flaking paint', NULL, 0, NULL, 2, 'physical', 4);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (5, 1, 'S5', 'A. Service Area', NULL, 'Both', 'Counters and display units clean; displayed food covered and temperature-held.', NULL, 0, NULL, 2, 'physical', 5);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (6, 1, 'S6', 'A. Service Area', NULL, 'Both', 'Service staff in clean uniform — cap, trimmed nails, no jewellery', NULL, 0, NULL, 2, 'physical', 6);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (7, 1, 'S7', 'A. Service Area', NULL, 'Both', 'No unwell staff on duty; cuts/wounds covered with waterproof dressing', NULL, 0, NULL, 2, 'physical', 7);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (8, 1, 'S8', 'A. Service Area', NULL, 'Both', 'Handwash or sanitiser available for guests and staff', NULL, 0, NULL, 2, 'physical', 8);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (9, 1, 'S9', 'A. Service Area', NULL, 'Both', 'Crockery, cutlery and glassware clean, chip-free, stored covered.', NULL, 0, NULL, 2, 'physical', 9);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (10, 1, 'S10', 'A. Service Area', NULL, 'Both', 'Drinking water potable/filtered; dispenser and jug clean', NULL, 0, NULL, 2, 'physical', 10);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (11, 1, 'S11', 'A. Service Area', NULL, 'Both', 'Table condiments/sachets within expiry date; containers clean', NULL, 0, NULL, 2, 'physical', 11);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (12, 1, 'S12', 'A. Service Area', NULL, 'Both', 'Waste bin covered, foot-operated, not overflowing', NULL, 0, NULL, 2, 'physical', 12);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (13, 1, 'S13', 'A. Service Area', NULL, 'Both', 'Restrooms clean and stocked; doors do not open directly into food area', NULL, 0, NULL, 2, 'physical', 13);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (14, 1, 'S14', 'A. Service Area', NULL, 'Both', 'Pest barrier functional at entrance (air curtain / insect-o-cutor); no signs of pests in dining area', NULL, 0, NULL, 2, 'physical', 14);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (15, 1, 'S15', 'A. Service Area', NULL, 'Both', 'Veg mark and allergen information on menu, where applicable', NULL, 0, NULL, 2, 'paperwork', 15);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (16, 1, 'K1', 'B. Kitchen Area', NULL, 'Both', 'No expired or undated items anywhere on the premises', NULL, 1, NULL, 4, 'physical', 16);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (17, 1, 'K2', 'B. Kitchen Area', NULL, 'Both', 'Decanted containers labelled with name and date; FIFO followed', NULL, 0, NULL, 2, 'physical', 17);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (18, 1, 'K3', 'B. Kitchen Area', NULL, 'Both', 'Storage 15 cm off the floor; no cartons or food on the floor.', NULL, 0, NULL, 2, 'physical', 18);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (19, 1, 'K4', 'B. Kitchen Area', NULL, 'Both', 'Raw and cooked food completely segregated', NULL, 1, NULL, 4, 'physical', 19);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (20, 1, 'K5', 'B. Kitchen Area', NULL, 'Both', 'Veg segregated in storage and prep', NULL, 1, NULL, 4, 'physical', 20);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (21, 1, 'K6', 'B. Kitchen Area', NULL, 'Both', 'Chiller ≤ 5°C, freezer − 18°C; temperature log up to date', NULL, 1, NULL, 4, 'physical', 21);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (22, 1, 'K7', 'B. Kitchen Area', NULL, 'Both', 'Hot holding ≥ 60°C; cooking to a core temperature ≥ 75°C', NULL, 0, NULL, 2, 'physical', 22);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (23, 1, 'K8', 'B. Kitchen Area', NULL, 'Both', 'Thawing only under refrigeration — never at room temperature', NULL, 0, NULL, 2, 'physical', 23);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (24, 1, 'K9', 'B. Kitchen Area', NULL, 'Both', 'Chemicals labelled and stored away from food', NULL, 0, NULL, 2, 'physical', 24);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (25, 1, 'K10', 'B. Kitchen Area', NULL, 'Both', 'Dry store clean, ventilated, pest-free.', NULL, 0, NULL, 2, 'physical', 25);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (26, 1, 'K11', 'B. Kitchen Area', NULL, 'Both', 'Colour-coded boards / separate prep tools in use', NULL, 0, NULL, 2, 'physical', 26);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (27, 1, 'K12', 'B. Kitchen Area', NULL, 'Both', 'Frying oil within TPC limit; oil-change log up to date', NULL, 0, NULL, 2, 'physical', 27);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (28, 1, 'K13', 'B. Kitchen Area', NULL, 'Both', 'Food-contact surfaces and equipment clean — no rust, damage or wooden patches', NULL, 0, NULL, 2, 'physical', 28);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (29, 1, 'K14', 'B. Kitchen Area', NULL, 'Both', 'Only approved colours/additives used; declaration on file', NULL, 0, NULL, 2, 'physical', 29);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (30, 1, 'K15', 'B. Kitchen Area', NULL, 'Both', 'Medical fitness certificate up to date for every food handler', NULL, 1, NULL, 4, 'paperwork', 30);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (31, 1, 'K16', 'B. Kitchen Area', NULL, 'Both', 'FoSTaC-certified supervisor on roster; certificate available', NULL, 0, NULL, 2, 'paperwork', 31);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (32, 1, 'K17', 'B. Kitchen Area', NULL, 'Both', 'Kitchen staff — cap, apron, trimmed nails, no jewellery; no smoking or paan', NULL, 0, NULL, 2, 'physical', 32);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (33, 1, 'K18', 'B. Kitchen Area', NULL, 'Both', 'Handwash stations stocked — soap, sanitiser, paper towel', NULL, 0, NULL, 2, 'physical', 33);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (34, 1, 'K19', 'B. Kitchen Area', NULL, 'Both', 'No pest activity; pest-control service record up to date; stations mapped', NULL, 1, NULL, 4, 'paperwork', 34);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (35, 1, 'K20', 'B. Kitchen Area', NULL, 'Both', 'Drain traps in place, flowing and clean; no standing water', NULL, 0, NULL, 2, 'physical', 35);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (36, 1, 'K21', 'B. Kitchen Area', NULL, 'Both', 'Waste segregated, bins covered, emptied daily', NULL, 0, NULL, 2, 'physical', 36);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (37, 1, 'K22', 'B. Kitchen Area', NULL, 'Both', 'Exhaust and hoods degreased; ventilation adequate; lights protected', NULL, 0, NULL, 2, 'physical', 37);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (38, 1, 'K23', 'B. Kitchen Area', NULL, 'Both', 'Water potability report valid — tested within the last 6 months', NULL, 1, NULL, 4, 'paperwork', 38);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (39, 1, 'K24', 'B. Kitchen Area', NULL, 'Both', 'Deep-cleaning schedule up to date and followed; dispense log with temperature (CK checklist)', NULL, 0, NULL, 2, 'paperwork', 39);
INSERT INTO templates (id, domain, scheme, name, description, version, frequency_days, active) VALUES (2, 'food', 'fssai2', 'FSSAI internal food safety audit (60-line checklist)', 'Used from Sep 2026. Lines that do not apply to a unit are removed as N/A. Lines 31, 37 and 50 were N/A in every report so far, so their wording is not on file yet.', 2, 30, 1);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (40, 2, 'L1', 'A. Service Area', 'Menu information', 'Restaurant', 'Veg / non-veg mark and allergen information on the menu (where applicable).', 'Pick up a menu card — every non-veg dish should carry a red mark and every veg dish a green one. Then choose three dishes containing peanut, sesame, milk or wheat and ask how the guest is told.', 0, NULL, 2, 'paperwork', 1);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (41, 2, 'L2', 'A. Service Area', 'Table items', 'Restaurant', 'Table condiments and sachets within their expiry date; containers clean.', 'Look at the bottom of the sauce bottles on three tables, and inside the sachet holder.', 0, NULL, 2, 'physical', 2);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (42, 2, 'L3', 'A. Service Area', 'Display / buffet', 'Restaurant', 'Counters and display units clean; displayed food covered and held at the correct temperature.', 'Probe the buffet while service is running and ask how long that tray has been out.', 0, NULL, 2, 'physical', 3);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (43, 2, 'L4', 'A. Service Area', 'Complaints', 'Both', 'A guest complaint system in place; investigation and closure recorded in the complaint register.', 'A register with zero complaints all year is not a good sign — it is an unused register.', 0, NULL, 2, 'paperwork', 4);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (44, 2, 'L5', 'A. Service Area', 'Crockery and cutlery', 'Restaurant', 'Crockery, cutlery and glassware clean, unchipped and stored covered.', 'Hold ten items up to the light. Watch how the runner picks up glasses — fingers inside the rim is a finding.', 0, NULL, 2, 'physical', 5);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (45, 2, 'L6', 'A. Service Area', 'Drinking water', 'Restaurant', 'Drinking water potable / filtered; dispenser and jug clean.', 'Trace where the guest water comes from. Open the dispenser and look at the drip tray.', 1, NULL, 4, 'physical', 6);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (46, 2, 'L7', 'A. Service Area', 'Ice', 'Restaurant', 'Ice for drinks made from potable water, kept covered, scoop stored outside the bin, no hand contact.', 'Look inside the ice bin. A glass used as a scoop, or a scoop buried in the ice, is an immediate finding.', 1, NULL, 4, 'physical', 7);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (47, 2, 'L8', 'A. Service Area', 'Guest washroom', 'Restaurant', 'Handwash or sanitiser available for guests and staff; restrooms clean and stocked; doors must not open directly into the food area.', 'Use it yourself. Check which way the door opens and whether the bin is covered.', 0, NULL, 2, 'physical', 8);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (48, 2, 'L9', 'A. Service Area', 'Service staff hygiene', 'Restaurant', 'Service staff in clean uniform, hands clean, hair tied, no jewellery; dishes carried without touching the food surface.', 'Stand at the pass and watch five dishes go out. This one is to be watched, not asked.', 0, NULL, 2, 'physical', 9);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (49, 2, 'L10', 'A. Service Area', 'Pest — dining', 'Restaurant', 'Pest barrier working at the entrance — air curtain / insect-o-cutor; no sign of pests in the dining area.', 'Check the insect killer tray and the window edges. Look under the fixed seating too.', 0, NULL, 2, 'physical', 10);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (50, 2, 'L11', 'A. Service Area', 'Waste', 'Both', 'Waste segregated, bins covered and foot-operated, waste cleared daily; the waste area washed down.', 'Go round the back. An outlet that looks good usually gets caught here.', 0, NULL, 2, 'physical', 11);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (51, 2, 'L12', 'A. Service Area', 'Illness', 'Both', 'No unwell staff on duty; cuts and wounds covered with a waterproof dressing.', 'Look at the staff''s hands — if there is a plaster, is it waterproof and coloured so it is visible? Ask the newest member what they do if they have diarrhoea or fever; the answer tells you whether the rule is real or only on paper.', 1, NULL, 4, 'physical', 12);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (52, 2, 'L13', 'B. Kitchen Area', 'Layout', 'Both', 'Enough room to work, clean and maintain, and a design that keeps dust, waste and pests out.', 'Find the spot where two people carrying hot pans have to pass each other, and the corners a mop cannot reach.', 0, NULL, 2, 'physical', 13);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (53, 2, 'L14', 'B. Kitchen Area', 'Construction', 'Both', 'Internal construction and fittings made of non-toxic, non-absorbent, smooth and cleanable material.', 'Run your hand along the prep counter and shelves. Wood, rust and peeling laminate are all findings.', 0, NULL, 2, 'physical', 14);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (54, 2, 'L15', 'B. Kitchen Area', 'Flooring', 'Both', 'Floor non-slip, sloped towards the drain, coving at the wall-floor joint; no cracks or broken tiles.', 'Walk the whole floor including under the racks. Pour a mug of water at the lowest point and see where it goes.', 0, NULL, 2, 'physical', 15);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (55, 2, 'L16', 'B. Kitchen Area', 'Segregation', 'Both', 'Raw and cooked / ready-to-eat areas separated; veg and non-veg separated in both prep and storage.', 'Colour-coded boards and knives should be in use, not lying in a drawer. Check the chiller shelves too.', 1, NULL, 4, 'physical', 16);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (56, 2, 'L17', 'B. Kitchen Area', 'Ventilation', 'Both', 'Adequate ventilation and an exhaust over the cooking line; no condensation or grease dripping onto food.', 'Tissue test at the edge of the hood. Check the duct joints and the ceiling above the range.', 0, NULL, 2, 'physical', 17);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (57, 2, 'L18', 'B. Kitchen Area', 'Drainage', 'Both', 'Drainage adequate, trapped and covered, flowing away from the food area; no cross-connection with potable water.', 'Look during the peak washing period, not at 4 pm. Smell at floor level for dry traps.', 0, NULL, 2, 'physical', 18);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (58, 2, 'L19', 'B. Kitchen Area', 'Handwashing', 'Both', 'A dedicated handwash basin at the entrance to the food area, with soap, running water and a means of drying hands.', 'Turn the tap on. A sink where vegetables are washed is not a handwash sink.', 0, NULL, 2, 'physical', 19);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (59, 2, 'L20', 'B. Kitchen Area', 'Temperature control', 'Both', 'Enough chilling, freezing and hot-holding capacity for the volume handled, each with a working thermometer.', 'Count the units against peak volume. An uncalibrated thermometer proves nothing.', 1, NULL, 4, 'physical', 20);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (60, 2, 'L21', 'B. Kitchen Area', 'Equipment', 'Both', 'Equipment of food-grade material, designed to be cleanable, in sound condition; measuring devices calibrated.', 'Look under the prep tables and behind the equipment. Ask for the calibration record for the probe and the scale.', 0, NULL, 2, 'physical', 21);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (61, 2, 'L22', 'B. Kitchen Area', 'Receiving', 'Both', 'Incoming goods checked and recorded — condition, temperature, date, vehicle cleanliness; rejections recorded too.', 'A register with no rejection ever recorded usually means nobody is checking.', 0, NULL, 2, 'paperwork', 22);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (62, 2, 'L23', 'B. Kitchen Area', 'Unsafe food', 'Both', 'Nothing expired, undated, unlabelled or visibly unsafe anywhere on the premises.', 'Open the back row of every shelf and the bottom of every freezer basket. That is where it hides.', 1, NULL, 4, 'physical', 23);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (63, 2, 'L24', 'B. Kitchen Area', 'Stock rotation', 'Both', 'FIFO followed; every stored item marked with the receipt or prep date and a use-by date.', 'Pick five containers at random. An unlabelled container is an undated container.', 0, NULL, 2, 'paperwork', 24);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (64, 2, 'L25', 'B. Kitchen Area', 'Storage', 'Both', 'Storage at least 15 cm off the floor and away from the wall; nothing kept under toilets, passages or sinks.', 'Look under the lowest rack and behind the doors.', 0, NULL, 2, 'physical', 25);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (65, 2, 'L26', 'B. Kitchen Area', 'Storage', 'Both', 'Raw and cooked separated; cooked and ready-to-eat stored above raw; everything in covered containers.', 'Open the chiller and look at the shelf order. Raw chicken above cooked rice is an immediate finding.', 1, NULL, 4, 'physical', 26);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (66, 2, 'L27', 'B. Kitchen Area', 'Cold chain', 'Both', 'Chillers at 5 °C or below, freezers at −18 °C or below; measured and logged at a set frequency, with action taken on exceptions.', 'Probe it yourself and compare with today''s log. A gap between probe and log is two findings.', 1, NULL, 4, 'physical', 27);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (67, 2, 'L28', 'B. Kitchen Area', 'Cooking', 'Both', 'Core cooking temperature 75 °C or above; hot holding 60 °C or above; cold display 5 °C or below.', 'Probe during service, not a sample made for you. Measure the centre of the thickest piece.', 1, NULL, 4, 'physical', 28);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (68, 2, 'L29', 'B. Kitchen Area', 'Thawing', 'Both', 'Thawing only under refrigeration, under running potable water or in a microwave — never in the open.', 'Check the sink and back counter during morning prep. This is a prep-time check, not a paper one.', 0, NULL, 2, 'physical', 29);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (69, 2, 'L30', 'B. Kitchen Area', 'Reheating', 'Both', 'Reheat to 75 °C or above, once only; a written policy for leftovers that staff can state.', 'Ask the chef what happens to leftover gravy at closing. The answer should match the written policy.', 0, NULL, 2, 'physical', 30);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (70, 2, 'L32', 'B. Kitchen Area', 'Additives', 'Both', 'Only approved additives and colours, within limits; declaration and supplier COA on file.', 'Look for unlabelled colour sachets in the spice store. This is a criminal-liability item.', 1, NULL, 4, 'physical', 31);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (71, 2, 'L33', 'B. Kitchen Area', 'Frying oil', 'Both', 'Frying oil TPC within limit, measured with a tester and recorded; used oil disposed of through a registered agency.', 'Ask for the oil tester and the last readings. Check the collection receipts for used oil.', 0, NULL, 2, 'physical', 32);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (72, 2, 'L34', 'B. Kitchen Area', 'Chemicals', 'Both', 'Cleaning chemicals and pesticides kept away from food, clearly labelled, in a lockable place.', 'A sanitiser bottle on the prep shelf is not convenience, it is an adulteration risk.', 1, NULL, 4, 'physical', 33);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (73, 2, 'L35', 'B. Kitchen Area', 'Packaging', 'Both', 'Food-contact packaging food grade, supplier certificate on file; not reused for other purposes.', 'Check what the oil tins and paint buckets at the back are being used for.', 0, NULL, 2, 'physical', 34);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (74, 2, 'L36', 'B. Kitchen Area', 'Labelling', 'CPK', 'Packed items labelled as the Labelling & Display regulations require — name, ingredients, allergens, veg / non-veg mark, packing date, use-by, FSSAI number, net weight.', 'Take one packed tray off the dispatch rack and check every point against the rule.', 1, NULL, 4, 'physical', 35);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (75, 2, 'L38', 'B. Kitchen Area', 'Transport', 'CPK', 'Vehicle food grade, clean and insulated; the cold chain held, with temperature recorded at dispatch and on arrival.', 'Open the vehicle. Probe one box on arrival at the outlet and compare it with the dispatch slip.', 1, NULL, 4, 'physical', 36);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (76, 2, 'L39', 'B. Kitchen Area', 'Sanitation', 'Both', 'Food-contact surfaces cleaned and sanitised between raw and cooked work; approved sanitiser at the correct strength.', 'Watch the sanitiser being made up. Check the dilution against the label, and whether test strips exist.', 1, NULL, 4, 'physical', 37);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (77, 2, 'L40', 'B. Kitchen Area', 'PPE', 'Both', 'Aprons, gloves, headgear and masks issued, in good condition, and changed at the right times.', 'Gloves not changed all morning are worse than no gloves at all.', 0, NULL, 2, 'physical', 38);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (78, 2, 'L41', 'C. Whole Premises and Documentation', 'FSSAI licence', 'Both', 'FSSAI licence valid, of the correct category, carrying this unit''s address, and displayed where it can be seen.', 'Read the licence yourself: validity date, category, address. A head-office licence does not cover this kitchen.', 1, NULL, 4, 'paperwork', 39);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (79, 2, 'L42', 'C. Whole Premises and Documentation', 'FSSAI licence', 'Both', 'The scope of the licence covers what is actually done here (a central kitchen that manufactures in bulk or repacks needs that endorsement).', 'Compare the ''kind of business'' printed on the licence with what is happening on the floor.', 1, NULL, 4, 'paperwork', 40);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (80, 2, 'L43', 'C. Whole Premises and Documentation', 'FSSAI licence', 'Both', 'FSSAI licence number printed on the menu, the bill and the label of every packed item.', 'Pick up one bill and one menu card. In a CPK, take one packed item off the dispatch rack.', 0, NULL, 2, 'paperwork', 41);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (81, 2, 'L44', 'C. Whole Premises and Documentation', 'Display', 'Both', 'Food Safety Display Board, hygiene rating certificate (if any), no-smoking and handwashing notices put up.', 'Walk the guest area and the kitchen entrance. A board behind a rack does not count as ''put up''.', 0, NULL, 2, 'paperwork', 42);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (82, 2, 'L45', 'C. Whole Premises and Documentation', 'Construction', 'Both', 'No plaster or paint flaking from walls, ceilings or doors; no condensation; no particles falling.', 'Torch the ceiling corners and behind the dishwash. Look directly above open food.', 0, NULL, 2, 'physical', 43);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (83, 2, 'L46', 'C. Whole Premises and Documentation', 'Lighting', 'Both', 'Enough light to work by; lights above open food shatterproof or covered.', 'Look up over every open-food surface. A bare tube over the prep table is a finding.', 0, NULL, 2, 'physical', 44);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (84, 2, 'L47', 'C. Whole Premises and Documentation', 'Water', 'Both', 'Adequate supply of potable water; water in contact with food potable; lab report within the required period.', 'Check the report date, the parameters tested, and that the sample point is this unit.', 1, NULL, 4, 'paperwork', 45);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (85, 2, 'L48', 'C. Whole Premises and Documentation', 'Water', 'Both', 'Water tank covered, cleaned to schedule with records; no algae or insects.', 'Open the lid and shine a torch. Ask for the last cleaning record with its date.', 0, NULL, 2, 'paperwork', 46);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (86, 2, 'L49', 'C. Whole Premises and Documentation', 'Supplier approval', 'Both', 'Raw material only from suppliers holding an FSSAI licence or registration; a copy of each supplier''s licence on file.', 'Take three suppliers off last month''s bills and find their licence copies. Check those are still in date as well.', 1, NULL, 4, 'physical', 47);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (87, 2, 'L51', 'C. Whole Premises and Documentation', 'Cleaning system', 'Both', 'Cleaning schedule up to date and signed; dispatch log with temperatures (CK outlets).', 'Take one line off the schedule and touch that surface yourself — signed but greasy is a finding, not a pass. For CPK/CK, check whether last week''s dispatch slips carry temperatures.', 0, NULL, 2, 'paperwork', 48);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (88, 2, 'L52', 'C. Whole Premises and Documentation', 'Pest control', 'Both', 'Pest control by a licensed agency at a set frequency; bait map and service records on file; no signs of pests.', 'Torch under the equipment and along the wall-floor joint first, then look at the records.', 1, NULL, 4, 'paperwork', 49);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (89, 2, 'L53', 'C. Whole Premises and Documentation', 'Medical fitness', 'Both', 'An annual medical fitness certificate for every food handler.', 'Count the certificates against today''s staff list, not last year''s. Check the dates.', 1, NULL, 4, 'paperwork', 50);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (90, 2, 'L54', 'C. Whole Premises and Documentation', 'Appearance', 'Both', 'Clean uniform, head covered, no jewellery, nails short and unpainted, no watches in the food area.', 'Not a team lined up for you — look at hands and hairlines during service.', 0, NULL, 2, 'physical', 51);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (91, 2, 'L55', 'C. Whole Premises and Documentation', 'Handwashing', 'Both', 'Hands washed at the designated point and at every change of task; cooked or ready-to-eat food never touched with bare hands.', 'Stand quietly at the pass for five minutes. This one is to be watched, not asked.', 1, NULL, 4, 'physical', 52);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (92, 2, 'L56', 'C. Whole Premises and Documentation', 'Conduct', 'Both', 'No smoking, spitting, eating or chewing in the food area; notices displayed and followed.', 'Not the main kitchen — check the back staircase and the store room.', 0, NULL, 2, 'physical', 53);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (93, 2, 'L57', 'C. Whole Premises and Documentation', 'FoSTaC', 'Both', 'One FoSTaC-trained Food Safety Supervisor for every 25 food handlers, with a valid certificate.', 'Count the handlers, count the certificates, check the expiry. This is a licence condition and it blocks renewal.', 1, NULL, 4, 'paperwork', 54);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (94, 2, 'L58', 'C. Whole Premises and Documentation', 'Training', 'Both', 'Induction and refresher food safety training for all handlers; records with date, topic and signature.', 'Take one name off the training list and ask that person what they were taught.', 0, NULL, 2, 'paperwork', 55);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (95, 2, 'L59', 'C. Whole Premises and Documentation', 'Records', 'Both', 'Records available and kept for one year or the shelf life, whichever is longer — temperature, cleaning, pest, water, oil, medical, training, supplier.', 'Ask for one specific date three months ago and see how long it takes to produce it.', 1, NULL, 4, 'paperwork', 56);
INSERT INTO template_items (id, template_id, code, section, area, applies, text, guidance, critical, criticality, weight, kind, sort) VALUES (96, 2, 'L60', 'C. Whole Premises and Documentation', 'Regulator follow-up', 'Both', 'Findings from the last FSO inspection or improvement notice closed within the deadline, with evidence.', 'Ask for the last inspection report. Even ''they have never come'' has to be evidenced by the file.', 0, NULL, 2, 'paperwork', 57);
INSERT INTO templates (id, domain, scheme, name, description, version, frequency_days, active) VALUES (3, 'maintenance', 'docket', 'Maintenance inspection docket (65 check points)', 'Internal maintenance walk-through. OK 1 point, Observation 0.5, Non-compliant 0.', 1, 30, 1);
